static string ltrim(string s) {
  size_t i = 0;
  while (i < s.size() && std::isspace(static_cast<unsigned char>(s[i]))) ++i;
  return s.substr(i);
}
string rtrim(string s) {
  while (!s.empty() && std::isspace(static_cast<unsigned char>(s.back()))) s.pop_back();
  return s;
}
string trim(string s) { return rtrim(ltrim(std::move(s))); }
bool starts_with(const string& s, const string& p) { return s.rfind(p, 0) == 0; }

string source_code_only(string line) {
  bool in_string = false, escaped = false;
  for (size_t index = 0; index < line.size(); ++index) {
    char ch = line[index];
    if (in_string) {
      line[index] = ' ';
      if (escaped) escaped = false;
      else if (ch == '\\') escaped = true;
      else if (ch == '"') in_string = false;
    } else if (ch == '"') {
      line[index] = ' ';
      in_string = true;
    } else if (ch == '#') {
      line.resize(index);
      break;
    }
  }
  return line;
}
bool ends_with(const string& s, const string& p) {
  return s.size() >= p.size() && s.compare(s.size() - p.size(), p.size(), p) == 0;
}

bool decimal_float_literal(const string& value) {
  size_t index = 0;
  if (index < value.size() && (value[index] == '+' || value[index] == '-'))
    ++index;
  auto digits = [&] {
    size_t start = index;
    while (index < value.size() &&
           std::isdigit(static_cast<unsigned char>(value[index])))
      ++index;
    return index != start;
  };
  bool before_point = digits();
  bool point = index < value.size() && value[index] == '.';
  bool after_point = false;
  if (point) {
    ++index;
    after_point = digits();
  }
  if (!before_point && !after_point) return false;
  bool exponent = index < value.size() &&
      (value[index] == 'e' || value[index] == 'E');
  if (exponent) {
    ++index;
    if (index < value.size() && (value[index] == '+' || value[index] == '-'))
      ++index;
    if (!digits()) return false;
  }
  return index == value.size() && (point || exponent);
}

string stable_hash(const string& value) {
  std::uint64_t hash = 14695981039346656037ULL;
  for (unsigned char byte : value) {
    hash ^= byte;
    hash *= 1099511628211ULL;
  }
  std::ostringstream out;
  out << std::hex << std::setfill('0') << std::setw(16) << hash;
  return out.str();
}

string tooling_name(string value) {
  for (char& c : value) {
    if (!std::isalnum(static_cast<unsigned char>(c)) && c != '_') c = '_';
  }
  while (!value.empty() && value.back() == '_') value.pop_back();
  return value.empty() ? "anonymous" : value;
}

string tooling_native_symbol(const string& kind, const string& name,
                                    const string& semantic_identity) {
  return "moss__" + tooling_name(kind) + "__" + tooling_name(name) + "__" +
      stable_hash(semantic_identity);
}

static bool rust_reserved_identifier(const string& value) {
  static const std::set<string> reserved = {
      "as","async","await","become","box","break","const","continue","crate",
      "do","dyn","else","enum","extern","false","final","fn","for","if","impl",
      "in","let","loop","macro","match","mod","move","override","priv","pub",
      "ref","return","static","struct","super","trait","true","try","type",
      "typeof","union","unsafe","unsized","use","virtual","where","while","yield"
  };
  return reserved.count(value) != 0;
}

string rust_identifier(const string& value) {
  return rust_reserved_identifier(value) ? "r#" + value : value;
}

vector<string> split_top_level(const string& s, char delim) {
  vector<string> out;
  int par = 0, br = 0, sq = 0;
  bool in_str = false, esc = false;
  size_t start = 0;
  for (size_t i = 0; i < s.size(); ++i) {
    char c = s[i];
    if (in_str) {
      if (esc) esc = false;
      else if (c == '\\') esc = true;
      else if (c == '"') in_str = false;
      continue;
    }
    if (c == '"') { in_str = true; continue; }
    if (c == '(') ++par; else if (c == ')') --par;
    else if (c == '{') ++br; else if (c == '}') --br;
    else if (c == '[') ++sq; else if (c == ']') --sq;
    else if (c == delim && par == 0 && br == 0 && sq == 0) {
      out.push_back(trim(s.substr(start, i - start)));
      start = i + 1;
    }
  }
  out.push_back(trim(s.substr(start)));
  return out;
}

string module_name_from_symbol(const string& symbol) {
  auto separator = symbol.find("__");
  return separator == string::npos ? string() : symbol.substr(0, separator);
}

// Identity of a module spelling in `program`. Standalone sources have no
// package manifest, so they share one compiler-defined local package; the
// compiler's own `std` module has a compiler-defined identity.
// Interns every nominal declaration of `program` exactly once (§3.1): its
// identity is the defining module identity plus the source declaration name.
void build_type_context(Program& program) {
  auto context = std::make_shared<moss::TypeContext>();
  for (auto& function : program.functions) {
    const string& declaration = function.declaration_name.empty()
        ? function.name : function.declaration_name;
    function.semantic_callable_id = "callable-v1:" +
        program_module_identity(program, function.defining_module) +
        ":fn:" + declaration;
  }
  auto declare = [&](moss::DeclarationKind kind, const string& program_name,
                     const string& defining_module, const string& declaration_name,
                     vector<moss::NominalFieldSlot> fields) {
    moss::NominalDeclaration declaration;
    declaration.kind = kind;
    declaration.program_name = program_name;
    declaration.module_id = program_module_identity(program, defining_module);
    declaration.declaration_name =
        declaration_name.empty() ? program_name : declaration_name;
    declaration.fields = std::move(fields);
    context->declare(std::move(declaration));
  };
  for (const auto& object : program.objects) {
    vector<moss::NominalFieldSlot> fields;
    for (const auto& field : object.fields) {
      const bool inferred = field.inferred || field.type.empty() ||
          (program.file_check_scope &&
           !program.file_scope_objects.count(object.name) &&
           !program.external_modules.count(
               module_name_from_symbol(object.name)));
      fields.push_back({field.name, inferred ? string() : trim(field.type), inferred});
    }
    declare(moss::DeclarationKind::Record, object.name, object.defining_module,
            object.declaration_name, std::move(fields));
  }
  for (const auto& enumeration : program.enums)
    declare(moss::DeclarationKind::Enum, enumeration.name,
            enumeration.defining_module, enumeration.declaration_name, {});
  for (const auto& domain : program.domains)
    declare(moss::DeclarationKind::Domain, domain.name, domain.defining_module,
            domain.declaration_name, {});
  context->register_trait("Iterator");
  for (const auto& trait : program.traits)
    context->register_trait(trait.name);
  try {
    context->bind_field_annotations();
  } catch (const moss::InvalidFieldAnnotation& invalid) {
    for (const auto& object : program.objects) {
      auto declaration = context->find(object.name);
      if (!declaration || declaration->id != invalid.declaration_id) continue;
      for (const auto& field : object.fields) {
        if (field.name != invalid.field_name) continue;
        CompileError error(field.line, invalid.what(), "MALFORMED_TYPE_EXPRESSION");
        error.source_file = field.source_file;
        throw error;
      }
    }
    throw;
  }
  program.type_context = std::move(context);
}

static bool belongs_to_module(const string& qualified, const string& module) {
  return qualified == module || starts_with(qualified, module + "__");
}

string specialization_calling_module(const Program& program,
                                            const string& context,
                                            const string& root_module) {
  if (starts_with(context, "fn:"))
    return module_name_from_symbol(context.substr(3));
  if (starts_with(context, "method:")) {
    string owner = context.substr(7);
    size_t dot = owner.find('.');
    return module_name_from_symbol(dot == string::npos ? owner : owner.substr(0, dot));
  }
  if (starts_with(context, "handler:")) {
    string owner = context.substr(8);
    size_t dot = owner.find('.');
    return module_name_from_symbol(dot == string::npos ? owner : owner.substr(0, dot));
  }
  // main, test, and benchmark bodies are projected into the root module.
  return !root_module.empty() ? root_module : program.main_module;
}

string canonical_type_name(string type) {
  type = trim(std::move(type));
  if (auto parsed = moss::Type::parse_canonical(type))
    return (*parsed)->to_canonical_string();
  if (type == "Int") return "int";
  if (type == "Float") return "float";
  if (type == "Bool") return "bool";
  if (type == "Char") return "char";
  if (type == "String") return "string";
  if (type == "Vector") return "vector";
  if (type == "Map") return "map";
  if (type == "Queue") return "queue";
  if (type == "Set") return "set";
  auto bracket = type.find('[');
  if (bracket != string::npos && ends_with(type, "]")) {
    string head = canonical_type_name(type.substr(0, bracket));
    auto arguments = split_top_level(type.substr(bracket + 1,
                                                  type.size() - bracket - 2), ',');
    for (auto& argument : arguments) {
      auto eq = argument.find('=');
      if (eq != string::npos) {
        string k = trim(argument.substr(0, eq));
        string v = canonical_type_name(argument.substr(eq + 1));
        argument = k + "=" + v;
      } else {
        argument = canonical_type_name(argument);
      }
    }
    std::ostringstream normalized;
    normalized << head << "[";
    for (size_t index = 0; index < arguments.size(); ++index) {
      if (index) normalized << ",";
      normalized << arguments[index];
    }
    normalized << "]";
    return normalized.str();
  }
  return type;
}

string canonical_type_name(const moss::TypeRef& type) {
  return type ? type->to_canonical_string() : string();
}

// A record instance with at least one substituted slot (`Box[value=int]`);
// a bare record spelling is its template or a fully declared record.
bool is_nominal_instance_type(const string& type) {
  auto parsed = moss::Type::parse_canonical(type);
  return parsed && (*parsed)->kind == moss::TypeKind::NominalInstance &&
         !(*parsed)->field_substitutions.empty();
}

string nominal_template_name(const string& type) {
  auto parsed = moss::Type::parse_canonical(type);
  return parsed && (*parsed)->kind == moss::TypeKind::NominalInstance
      ? (*parsed)->name : canonical_type_name(type);
}

std::vector<std::pair<string, string>> nominal_field_substitutions(const string& type) {
  std::vector<std::pair<string, string>> result;
  auto parsed = moss::Type::parse_canonical(type);
  if (!parsed || (*parsed)->kind != moss::TypeKind::NominalInstance) return result;
  for (const auto& field : (*parsed)->field_substitutions)
    result.emplace_back(field.first, field.second->to_canonical_string());
  return result;
}

std::optional<string> nominal_field_type(const string& type, const string& field_name) {
  for (const auto& sub : nominal_field_substitutions(type)) {
    if (sub.first == field_name) return sub.second;
  }
  return std::nullopt;
}

static bool standard_error_short_name(const string& name) {
  return name == "FileError" || name == "ParseError" ||
         name == "ConversionError";
}

string standard_error_identity(const string& name) {
  return "std__" + name;
}

vector<string> standard_error_variants(const string& identity) {
  if (identity == "std__FileError")
    return {"NotFound", "PermissionDenied", "NotRegularFile", "InUse",
            "Full", "IO"};
  if (identity == "std__ParseError") return {"Invalid", "Overflow"};
  if (identity == "std__ConversionError") return {"NonFinite", "Overflow"};
  return {};
}

// The standard namespace is compiler-owned.  Rewrite source tokens before
// parsing so every checker and backend path sees one nominal identity.  A
// module's own enum retains its separate identity; a qualified provider enum
// is never captured by the unqualified shorthand.
void normalize_standard_error_lines(
    vector<Line>& lines, const std::set<string>& forced_aliases) {
  bool explicit_module = false;
  std::set<string> local_names;
  for (const auto& line : lines) {
    const string code = trim(source_code_only(line.text));
    if (starts_with(code, "module ")) explicit_module = true;
    string declaration = starts_with(code, "export ")
        ? trim(code.substr(7)) : code;
    if (starts_with(declaration, "enum ")) {
      const string name = trim(declaration.substr(5,
          declaration.find(':') == string::npos ? string::npos :
          declaration.find(':') - 5));
      if (standard_error_short_name(name)) local_names.insert(name);
    }
  }
  for (const auto& alias : forced_aliases) local_names.erase(alias);
  for (auto& line : lines) {
    string rewritten;
    bool in_string = false;
    const string& value = line.text;
    for (size_t at = 0; at < value.size();) {
      if (value[at] == '"' && (at == 0 || value[at - 1] != '\\'))
        in_string = !in_string;
      if (!in_string && value[at] == '#') {
        rewritten += value.substr(at);
        break;
      }
      if (in_string || !(std::isalpha(static_cast<unsigned char>(value[at])) ||
                         value[at] == '_')) {
        rewritten.push_back(value[at++]);
        continue;
      }
      size_t end = at + 1;
      while (end < value.size() &&
             (std::isalnum(static_cast<unsigned char>(value[end])) ||
              value[end] == '_')) ++end;
      const string token = value.substr(at, end - at);
      if (token == "std" && end < value.size() && value[end] == '.') {
        size_t member = end + 1;
        while (member < value.size() &&
               (std::isalnum(static_cast<unsigned char>(value[member])) ||
                value[member] == '_')) ++member;
        const string name = value.substr(end + 1, member - end - 1);
        if (standard_error_short_name(name)) {
          rewritten += standard_error_identity(name);
          at = member;
          continue;
        }
      }
      if (standard_error_short_name(token) &&
          (!explicit_module || !local_names.count(token)) &&
          (at == 0 || value[at - 1] != '.'))
        rewritten += standard_error_identity(token);
      else rewritten += token;
      at = end;
    }
    line.text = std::move(rewritten);
  }
}

// Iterator ownership is a concrete specialization fact. Built-in Range and
// Vector traversal read their source; a custom Iterator uses next()'s actual
// receiver effect. The checker and native lowering share this decision.
template <typename ObjectMap>
Effect specialized_iterator_parameter_effect(
    const Function& function, size_t index, const string& concrete_type,
    const ObjectMap& objects) {
  Effect effect = index < function.parameter_effects.size()
      ? function.parameter_effects[index] : Effect::Read;
  if (index >= function.params.size() || concrete_type.empty()) return effect;
  const string& parameter = function.params[index].name;
  bool iterates = std::any_of(
      function.constraints.begin(), function.constraints.end(),
      [&](const Constraint& constraint) {
        return constraint.kind == ConstraintKind::Iterable &&
            constraint.subject == parameter &&
            constraint.detail == "static iterator";
      });
  if (!iterates) return effect;
  auto object = objects.find(canonical_type_name(concrete_type));
  if (object == objects.end()) return effect;
  for (const auto& method : object->second->methods)
    if (method.name == "next" && method.params.empty() &&
        static_cast<int>(method.receiver_effect) > static_cast<int>(effect))
      effect = method.receiver_effect;
  return effect;
}

// The structural term of a declared or projected type spelling, whether or
// not it is closed: `map` and `vector[_generic:x]` parse here.
moss::TypeRef parsed_type(const string& spelling) {
  auto parsed = moss::Type::parse_canonical(canonical_type_name(spelling));
  return parsed ? *parsed : nullptr;
}

moss::TypeRef parsed_type(const moss::TypeRef& type) {
  return type;
}

bool primitive_term(const moss::TypeRef& type, std::string_view name) {
  return type && type->kind == moss::TypeKind::Primitive && type->name == name;
}


// Resolve the closed Moss numeric operator relation shared by ordinary
// specialization and checked ABI-v10 import. The result is derived from both
// operands, so an imported relation cannot substitute an arbitrary result.
BuiltinOperatorAdmission admit_typed_arithmetic_operator(
    const string& operation, const moss::TypeRef& subject,
    const moss::TypeRef& argument, const moss::TypeRef& result) {
  if (operation != "operator:*" && operation != "operator:+" &&
      operation != "operator:-" && operation != "operator:/")
    return BuiltinOperatorAdmission::Rejected;
  if (!subject || !argument || !result || !subject->is_closed() ||
      !argument->is_closed() || !result->is_closed())
    return BuiltinOperatorAdmission::Deferred;
  const bool subject_numeric = primitive_term(subject, "int") ||
      primitive_term(subject, "float");
  const bool argument_numeric = primitive_term(argument, "int") ||
      primitive_term(argument, "float");
  if (!subject_numeric || !argument_numeric)
    return BuiltinOperatorAdmission::Rejected;
  const auto expected = primitive_term(subject, "float") ||
          primitive_term(argument, "float")
      ? moss::Type::primitive("float") : moss::Type::primitive("int");
  if (!expected || !result->structurally_equal(*expected))
    return BuiltinOperatorAdmission::Rejected;
  return BuiltinOperatorAdmission::Admitted;
}

BuiltinOperatorAdmission admit_typed_numeric_comparison(
    const string& operation, const moss::TypeRef& subject,
    const moss::TypeRef& argument, const moss::TypeRef& result) {
  if (operation != "operator:<" && operation != "operator:>" &&
      operation != "operator:<=" && operation != "operator:>=")
    return BuiltinOperatorAdmission::Rejected;
  if (!subject || !argument || !result || !subject->is_closed() ||
      !argument->is_closed() || !result->is_closed())
    return BuiltinOperatorAdmission::Deferred;
  const bool subject_numeric = primitive_term(subject, "int") ||
      primitive_term(subject, "float");
  const bool argument_numeric = primitive_term(argument, "int") ||
      primitive_term(argument, "float");
  if (!subject_numeric || !argument_numeric ||
      !primitive_term(result, "bool"))
    return BuiltinOperatorAdmission::Rejected;
  return BuiltinOperatorAdmission::Admitted;
}

// A parameterized built-in application named one of `names`.
bool applied_builtin(const moss::TypeRef& type,
                            std::initializer_list<std::string_view> names) {
  if (!type || type->kind != moss::TypeKind::Builtin || type->type_args.empty())
    return false;
  return std::find(names.begin(), names.end(), type->name) != names.end();
}

// A built-in collection, bare or applied, named one of `names`.
bool collection_named(const moss::TypeRef& type,
                             std::initializer_list<std::string_view> names) {
  if (!type || type->kind != moss::TypeKind::Builtin) return false;
  return std::find(names.begin(), names.end(), type->name) != names.end();
}

// The type an index expression yields: a vector's or queue's element, or a
// map's value. `seq` is not indexable and is deliberately absent.
std::optional<string> indexed_element(const moss::TypeRef& type) {
  if (applied_builtin(type, {"vector", "queue"}) && type->type_args.size() == 1)
    return type->type_args[0]->to_canonical_string();
  if (applied_builtin(type, {"map"}) && type->type_args.size() == 2)
    return type->type_args[1]->to_canonical_string();
  return std::nullopt;
}

// The open generic placeholder `_generic:<name>`, which stands for a type the
// checker has not bound yet. Centralized so the A2 conversion to a real
// inference variable with requirements (TYPE_IR_CONTRACT §§2, 4) has one
// place to change, rather than two dozen prefix tests.
bool open_generic(const string& type) {
  return starts_with(type, "_generic:") || starts_with(type, "_typevar:");
}

bool open_generic(const moss::TypeRef& type) {
  if (!type) return false;
  if (type->kind == moss::TypeKind::InferenceVar) return true;
  return open_generic(type->to_canonical_string());
}

// Statically bounded callable identity. Canonical identities use `callable-v1:`;
// legacy strings may carry `callable:`.
[[maybe_unused]] static bool is_canonical_callable_id(const string& type) {
  return starts_with(type, "callable-v1:");
}

bool callable_identity(const string& type) {
  return starts_with(type, "callable:") || starts_with(type, "callable-v1:");
}

bool callable_identity(const moss::TypeRef& type) {
  if (!type) return false;
  return callable_identity(type->to_canonical_string());
}

// An open built-in collection: named, with no type arguments yet.
bool bare_collection(const moss::TypeRef& type,
                            std::initializer_list<std::string_view> names) {
  if (!type || type->kind != moss::TypeKind::Builtin || !type->type_args.empty())
    return false;
  return std::find(names.begin(), names.end(), type->name) != names.end();
}

// A bare collection spelling (`vector`) against an application of that same
// collection (`vector[int]`): the open literal takes the declared type.
bool bare_matches_applied(const string& bare, const string& applied) {
  const auto open = parsed_type(bare);
  const auto declared = parsed_type(applied);
  return open && declared && open->kind == moss::TypeKind::Builtin &&
         open->type_args.empty() && declared->kind == moss::TypeKind::Builtin &&
         !declared->type_args.empty() && declared->name == open->name;
}

// Map built-ins need the concrete key/value types in the checker and native
// backend. Keep that decoding in one place so their type and lowering rules
// cannot drift apart.
std::optional<std::pair<string, string>> map_key_value_types(
    const string& type) {
  const auto term = parsed_type(type);
  if (!applied_builtin(term, {"map"}) || term->type_args.size() != 2)
    return std::nullopt;
  return std::make_pair(term->type_args[0]->to_canonical_string(),
                        term->type_args[1]->to_canonical_string());
}

// Authoritative compiler-owned surface for receiver builtins.  Type checking
// owns the operation set; editor completion projects these same descriptors.
static const vector<BuiltinOperationDescriptor>& builtin_operations() {
  static const vector<BuiltinOperationDescriptor> operations = {
      {BuiltinReceiverFamily::Vector, "push", "push(item)", "unit", Effect::Write, {Effect::Consume}, {"$element"}},
      {BuiltinReceiverFamily::Vector, "pop", "pop()", "$element", Effect::Write, {}, {}, true},
      {BuiltinReceiverFamily::Map, "get", "get(key, default)", "$value", Effect::Read, {Effect::Read, Effect::Read}, {"$key", "$value"}},
      {BuiltinReceiverFamily::Map, "keys", "keys()", "$keys", Effect::Read, {}, {}},
      {BuiltinReceiverFamily::Map, "values", "values()", "$values", Effect::Read, {}, {}},
      {BuiltinReceiverFamily::Map, "delete", "delete(key, fallback, found)", "$value", Effect::Write, {Effect::Read, Effect::Consume, Effect::Write}, {"$key", "$value", "bool"}},
      {BuiltinReceiverFamily::Queue, "push", "push(item)", "unit", Effect::Write, {Effect::Consume}, {"$element"}},
      {BuiltinReceiverFamily::Queue, "pop", "pop()", "$element", Effect::Write, {}, {}, true},
      {BuiltinReceiverFamily::Set, "insert", "insert(key)", "unit", Effect::Write, {Effect::Consume}, {"$element"}},
      {BuiltinReceiverFamily::Set, "contains", "contains(key)", "bool", Effect::Read, {Effect::Read}, {"$element"}},
      {BuiltinReceiverFamily::Set, "values", "values()", "$setvalues", Effect::Read, {}, {}},
      {BuiltinReceiverFamily::String, "length", "length()", "int", Effect::Read, {}, {}},
      {BuiltinReceiverFamily::String, "char_at", "char_at(index)", "char", Effect::Read, {Effect::Read}, {"int"}, true},
      {BuiltinReceiverFamily::String, "chars", "chars()", "vector[char]", Effect::Read, {}, {}},
      {BuiltinReceiverFamily::String, "find", "find(pattern)", "int", Effect::Read, {Effect::Read}, {"string"}},
      {BuiltinReceiverFamily::String, "slice", "slice(start, length)", "string", Effect::Read, {Effect::Read, Effect::Read}, {"int", "int"}},
      {BuiltinReceiverFamily::String, "ascii_lower", "ascii_lower()", "string", Effect::Read, {}, {}},
      {BuiltinReceiverFamily::String, "ascii_upper", "ascii_upper()", "string", Effect::Read, {}, {}},
      {BuiltinReceiverFamily::String, "reserve", "reserve(additional_bytes)", "unit", Effect::Write, {Effect::Read}, {"int"}},
      {BuiltinReceiverFamily::String, "append", "append(part)", "unit", Effect::Write, {Effect::Read}, {"string"}},
      {BuiltinReceiverFamily::String, "split", "split(separator)", "vector[string]", Effect::Read, {Effect::Read}, {"string"}, true},
      {BuiltinReceiverFamily::String, "join", "join(parts)", "string", Effect::Read, {Effect::Read}, {"vector[string]"}},
      {BuiltinReceiverFamily::String, "less", "less(other)", "bool", Effect::Read, {Effect::Read}, {"string"}},
      {BuiltinReceiverFamily::String, "isequal", "isequal(other)", "bool", Effect::Read, {Effect::Read}, {"string"}},
      {BuiltinReceiverFamily::String, "hash", "hash()", "int", Effect::Read, {}, {}},
      {BuiltinReceiverFamily::Char, "to_string", "to_string()", "string", Effect::Read, {}, {}},
      {BuiltinReceiverFamily::Char, "codepoint", "codepoint()", "int", Effect::Read, {}, {}},
      {BuiltinReceiverFamily::Char, "less", "less(other)", "bool", Effect::Read, {Effect::Read}, {"char"}},
      {BuiltinReceiverFamily::Char, "isequal", "isequal(other)", "bool", Effect::Read, {Effect::Read}, {"char"}},
      {BuiltinReceiverFamily::Char, "hash", "hash()", "int", Effect::Read, {}, {}},
      {BuiltinReceiverFamily::Int, "to_string", "to_string()", "string", Effect::Read, {}, {}},
      {BuiltinReceiverFamily::Int, "less", "less(other)", "bool", Effect::Read, {Effect::Read}, {"int"}},
      {BuiltinReceiverFamily::Int, "isequal", "isequal(other)", "bool", Effect::Read, {Effect::Read}, {"int"}},
      {BuiltinReceiverFamily::Int, "hash", "hash()", "int", Effect::Read, {}, {}},
      {BuiltinReceiverFamily::Float, "to_string", "to_string()", "string", Effect::Read, {}, {}},
      {BuiltinReceiverFamily::Float, "less", "less(other)", "bool", Effect::Read, {Effect::Read}, {"float"}},
      {BuiltinReceiverFamily::Float, "isequal", "isequal(other)", "bool", Effect::Read, {Effect::Read}, {"float"}},
      {BuiltinReceiverFamily::Float, "hash", "hash()", "int", Effect::Read, {}, {}},
      {BuiltinReceiverFamily::Bool, "to_string", "to_string()", "string", Effect::Read, {}, {}},
      {BuiltinReceiverFamily::Bool, "less", "less(other)", "bool", Effect::Read, {Effect::Read}, {"bool"}},
      {BuiltinReceiverFamily::Bool, "isequal", "isequal(other)", "bool", Effect::Read, {Effect::Read}, {"bool"}},
      {BuiltinReceiverFamily::Bool, "hash", "hash()", "int", Effect::Read, {}, {}},
  };
  return operations;
}

std::optional<BuiltinReceiverFamily> builtin_receiver_family(
    const string& type) {
  string concrete = canonical_type_name(type);
  const auto term = parsed_type(concrete);
  if (collection_named(term, {"vector"})) return BuiltinReceiverFamily::Vector;
  if (collection_named(term, {"map"})) return BuiltinReceiverFamily::Map;
  if (collection_named(term, {"queue"})) return BuiltinReceiverFamily::Queue;
  if (staged_abi_v10() && collection_named(term, {"set"})) return BuiltinReceiverFamily::Set;
  if (primitive_term(term, "string")) return BuiltinReceiverFamily::String;
  if (primitive_term(term, "char")) return BuiltinReceiverFamily::Char;
  if (primitive_term(term, "int")) return BuiltinReceiverFamily::Int;
  if (primitive_term(term, "float")) return BuiltinReceiverFamily::Float;
  if (primitive_term(term, "bool")) return BuiltinReceiverFamily::Bool;
  return std::nullopt;
}

const BuiltinOperationDescriptor* builtin_operation(
    const string& receiver_type, const string& name) {
  auto family = builtin_receiver_family(receiver_type);
  if (!family) return nullptr;
  auto operation = std::find_if(
      builtin_operations().begin(), builtin_operations().end(),
      [&](const BuiltinOperationDescriptor& candidate) {
        return candidate.receiver == *family && candidate.name == name;
      });
  return operation == builtin_operations().end() ? nullptr : &*operation;
}

// Instantiate both argument and result relationships from the same receiver.
std::optional<string> builtin_operation_type(
    const string& receiver_type, const string& pattern) {
  if (pattern == "$element") {
    string concrete = canonical_type_name(receiver_type);
    auto open = concrete.find('[');
    if (open == string::npos || !ends_with(concrete, "]")) return std::nullopt;
    return concrete.substr(open + 1, concrete.size() - open - 2);
  }
  if (pattern == "$setvalues") {
    auto term = parsed_type(receiver_type);
    if (!applied_builtin(term, {"set"}) || term->type_args.size() != 1)
      return std::nullopt;
    return "vector[" + term->type_args[0]->to_canonical_string() + "]";
  }
  if (!pattern.empty() && pattern.front() == '$') {
    auto types = map_key_value_types(receiver_type);
    if (!types) return std::nullopt;
    if (pattern == "$key") return types->first;
    if (pattern == "$value") return types->second;
    return "vector[" + (pattern == "$keys" ? types->first : types->second) + "]";
  }
  return pattern;
}

std::optional<string> builtin_operation_result(
    const string& receiver_type, const string& name, size_t arity) {
  const auto* operation = builtin_operation(receiver_type, name);
  if (!operation || operation->argument_types.size() != arity) return std::nullopt;
  return builtin_operation_type(receiver_type, operation->result);
}

std::optional<BuiltinReceiverFamily> builtin_receiver_family(
    const moss::TypeRef& type) {
  if (!type) return std::nullopt;
  if (collection_named(type, {"vector"})) return BuiltinReceiverFamily::Vector;
  if (collection_named(type, {"map"})) return BuiltinReceiverFamily::Map;
  if (collection_named(type, {"queue"})) return BuiltinReceiverFamily::Queue;
  if (staged_abi_v10() && collection_named(type, {"set"})) return BuiltinReceiverFamily::Set;
  if (primitive_term(type, "string")) return BuiltinReceiverFamily::String;
  return std::nullopt;
}

static bool nominal_key_method_pure_read(const Method& method) {
  return method.receiver_effect == Effect::Read &&
      std::all_of(method.parameter_effects.begin(),
                  method.parameter_effects.end(),
                  [](Effect effect) { return effect == Effect::Read; }) &&
      !method.observable_effects.local_capture_read &&
      method.observable_effects.fusion_safe() &&
      !method.observable_effects.fileio_unknown &&
      !method.observable_effects.may_diverge;
}

std::optional<std::pair<const Method*, const Method*>>
nominal_key_methods(const ObjectType& object, const string& key_type) {
  const Method* equality = nullptr;
  const Method* hash = nullptr;
  for (const auto& method : object.methods) {
    if (method.name == "isequal") {
      if (equality) return std::nullopt;
      equality = &method;
    } else if (method.name == "hash") {
      if (hash) return std::nullopt;
      hash = &method;
    }
  }
  if (!equality || !hash || equality->params.size() != 1 ||
      canonical_type_name(equality->params[0].type) != key_type ||
      !equality->return_type ||
      canonical_type_name(*equality->return_type) != "bool" ||
      equality->parameter_effects.size() != 1 ||
      !nominal_key_method_pure_read(*equality) ||
      !hash->params.empty() || !hash->return_type ||
      canonical_type_name(*hash->return_type) != "int" ||
      !hash->parameter_effects.empty() ||
      !nominal_key_method_pure_read(*hash)) return std::nullopt;
  return std::make_pair(equality, hash);
}

bool nominal_key_free_target(const Function& function,
                                    const string& key_type) {
  const size_t separator = function.name.rfind("__");
  const string name = separator == string::npos
      ? function.name : function.name.substr(separator + 2);
  if (name == "hash" && function.params.size() == 1)
    return canonical_type_name(function.params[0].type) == key_type;
  if (name == "isequal" && function.params.size() == 2)
    return canonical_type_name(function.params[0].type) == key_type &&
        canonical_type_name(function.params[1].type) == key_type;
  return false;
}

abi_v10::Record nominal_key_proof_record(
    const ObjectType& object, const string& declaration_id);

string keyed_operation_specialization_id(
    const string& key_type, const string& proof_id,
    const string& family, const string& operation) {
  moss::SpecializationKey key;
  key.callable_id = "builtin:key-protocol-v1:" + family + "." + operation;
  key.receiver = parsed_type(key_type);
  key.key_proof_id = proof_id;
  const auto identity = key.stable_key();
  synchronization_require(identity.has_value(),
                          "key operation requires a closed proven key type");
  return *identity;
}

const BuiltinOperationDescriptor* builtin_operation(
    const moss::TypeRef& receiver_type, const string& name) {
  auto family = builtin_receiver_family(receiver_type);
  if (!family) return nullptr;
  auto operation = std::find_if(
      builtin_operations().begin(), builtin_operations().end(),
      [&](const BuiltinOperationDescriptor& candidate) {
        return candidate.receiver == *family && candidate.name == name;
      });
  return operation == builtin_operations().end() ? nullptr : &*operation;
}

std::optional<string> builtin_operation_result(
    const moss::TypeRef& receiver_type, const string& name, size_t arity) {
  return builtin_operation_result(canonical_type_name(receiver_type), name, arity);
}

bool contains_internal_placeholder(const string& type) {
  string value = trim(type);
  if (internal_semantic_placeholder(value)) return true;
  auto open = value.find('[');
  if (open == string::npos || !ends_with(value, "]")) return false;
  for (auto part : split_top_level(value.substr(open + 1, value.size() - open - 2), ',')) {
    // A nominal instance substitutes named fields: `Box[s=_generic:x]`.
    const auto equals = part.find('=');
    if (equals != string::npos && equals < part.find('['))
      part = part.substr(equals + 1);
    if (contains_internal_placeholder(part)) return true;
  }
  return false;
}

bool contains_internal_placeholder(const moss::TypeRef& type) {
  if (!type) return false;
  if (type->kind == moss::TypeKind::InferenceVar) return true;
  return contains_internal_placeholder(type->to_canonical_string());
}


// The concrete effect is semantic metadata; both native sides derive their
// passing mode from this one decision. Primitive WRITE retains Moss's existing
// write-through ABI; ordinary Copy arguments are values.
ConcreteParameterABI concrete_parameter_abi(Effect effect,
                                                   const string& type) {
  return {effect, effect == Effect::Write ? ParameterPassingMode::MutableBorrow :
      effect == Effect::Consume || copy_type_name(canonical_type_name(type))
          ? ParameterPassingMode::Value : ParameterPassingMode::SharedBorrow};
}
// The one specialization identity (TYPE_IR_CONTRACT §3.3). Legacy typed
// strings enter at this boundary only; all key material is checked Type IR.
std::optional<moss::SpecializationKey> specialization_key_inputs(
    const string& callable_id, const vector<string>& types,
    const std::optional<moss::TypeRef>& receiver,
    const vector<std::pair<uint32_t, moss::TypeRef>>& open_result_bindings) {
  moss::SpecializationKey key;
  key.callable_id = callable_id;
  key.receiver = receiver;
  key.open_result_bindings = open_result_bindings;
  for (size_t index = 0; index < types.size(); ++index) {
    const auto& type = types[index];
    // A static higher-order argument is a resolved callable identity, not a
    // type or the lookup spelling used by its caller.
    if (starts_with(type, "callable-v1:")) {
      key.arguments.push_back(moss::Type::unit());
      key.callable_arguments.push_back(type);
      continue;
    }
    if (callable_identity(type)) {
      const string cid = starts_with(type, "callable:") ? type.substr(9) : type;
      if (!starts_with(cid, "callable-v1:")) return std::nullopt;
      key.arguments.push_back(moss::Type::unit());
      key.callable_arguments.push_back(cid);
      continue;
    }
    auto parsed = moss::Type::parse_canonical(canonical_type_name(type));
    if (!parsed || !(*parsed)->is_closed()) return std::nullopt;
    key.arguments.push_back(*parsed);
  }
  if (!key.stable_key()) return std::nullopt;
  return key;
}

static string semantic_call_site_identity(const SemanticCallEdge& edge) {
  string identity = edge.source +
      (edge.source_specialization_key.empty()
          ? string() : "#" + edge.source_specialization_key) +
      "@" + std::to_string(edge.line) + ":call:" + edge.target;
  if (edge.occurrence != 0)
    identity += ":occurrence:" + std::to_string(edge.occurrence + 1);
  return identity;
}

const FunctionSpecialization* concrete_specialization(
    const Function& function, const vector<string>& types) {
  const FunctionSpecialization* selected = nullptr;
  vector<string> canonical_types;
  for (const auto& type : types) canonical_types.push_back(canonical_type_name(type));
  for (const auto& candidate : function.specializations) {
    if (candidate.parameter_types != canonical_types) continue;
    if (candidate.semantic_key.stable_key() !=
        std::optional<string>(candidate.stable_type_key)) return nullptr;
    // A parameter-only lookup is valid only when it names one checked
    // instance. Result-bound calls supply the exact key at their call site.
    if (selected) return nullptr;
    selected = &candidate;
  }
  return selected;
}

const FunctionSpecialization* functional_specialization(
    const Function& function, const vector<string>& types) {
  // Functional registration uses this exact no-receiver, no-result-binding
  // key. Ordinary calls of the same parameter types may have other keys.
  auto key = specialization_key_inputs(function.semantic_callable_id, types);
  if (!key || !key->stable_key()) return nullptr;
  auto selected = std::find_if(function.specializations.begin(),
                               function.specializations.end(),
                               [&](const FunctionSpecialization& candidate) {
    return candidate.stable_type_key == *key->stable_key();
  });
  return selected == function.specializations.end() ? nullptr : &*selected;
}

// Effect a sort key applies to its element: the concrete specialization's
// for untyped keys, otherwise the declared function's.
Effect sort_key_effect(const Function& function, const string& element) {
  if (const auto* special = concrete_specialization(function, {element}))
    if (!special->parameter_effects.empty()) return special->parameter_effects.front();
  return function.parameter_effects.empty() ? Effect::Read
                                            : function.parameter_effects.front();
}

bool parse_index(const string& text, string& base, string& index) {
  string value = trim(text);
  if (value.empty() || value.back() != ']') return false;
  int depth = 0; bool in_str = false;
  for (size_t i = value.size(); i-- > 0;) {
    char c = value[i];
    if (in_str) { if (c == '"' && (i == 0 || value[i-1] != '\\')) in_str = false; continue; }
    if (c == '"') { in_str = true; continue; }
    if (c == ']') ++depth;
    else if (c == '[' && --depth == 0) {
      base = trim(value.substr(0, i)); index = trim(value.substr(i + 1, value.size() - i - 2));
      return !base.empty() && !index.empty();
    }
  }
  return false;
}

bool parse_simple_call(const string& text, string& callee, vector<string>& args) {
  string value = trim(text);
  auto lp = value.find('(');
  auto rp = value.rfind(')');
  if (lp == string::npos || rp != value.size() - 1 || lp == 0) return false;
  // The callee's '(' must close at the final ')': `Char(65).to_string()` is a
  // member call on a call result, not a call of `Char`.
  int depth = 0;
  for (size_t i = lp; i < value.size(); ++i) {
    char c = value[i];
    if (c == '"' || c == '\'') {
      for (++i; i < value.size() && value[i] != c; ++i)
        if (value[i] == '\\') ++i;
      continue;
    }
    if (c == '(' || c == '[' || c == '{') ++depth;
    else if ((c == ')' || c == ']' || c == '}') && --depth == 0 && i != rp) return false;
  }
  callee = trim(value.substr(0, lp));
  if (callee.empty()) return false;
  string inside = value.substr(lp + 1, rp - lp - 1);
  args.clear();
  if (!trim(inside).empty()) args = split_top_level(inside, ',');
  return true;
}

// Built-in typed collection construction is an expression form, not general
// local annotation syntax or generic nominal construction. Keep this syntax
// recognition shared between semantic and native paths.
std::optional<string> typed_empty_vector_constructor(const string& text) {
  string callee;
  vector<string> args;
  if (!parse_simple_call(text, callee, args) || !args.empty()) return std::nullopt;
  string type = canonical_type_name(callee);
  // Recognize the constructor spelling only; INVALID_TYPED_VECTOR_CONSTRUCTOR
  // reports a wrong arity later, so this must not reject it here.
  if (!starts_with(type, "vector[") || !ends_with(type, "]"))
    return std::nullopt;
  return type;
}

bool plain_identifier(const string& value) {
  string s = trim(value);
  if (s.empty() || !(std::isalpha(static_cast<unsigned char>(s.front())) || s.front() == '_')) return false;
  return std::all_of(s.begin() + 1, s.end(), [](char c) {
    return std::isalnum(static_cast<unsigned char>(c)) || c == '_';
  });
}

bool is_single_string_literal(const string& value) {
  string s = trim(value);
  if (s.size() < 2 || s.front() != '"' || s.back() != '"') return false;
  bool escaped = false;
  for (size_t i = 1; i < s.size() - 1; ++i) {
    if (escaped) escaped = false;
    else if (s[i] == '\\') escaped = true;
    else if (s[i] == '"') return false;
  }
  return !escaped;
}

bool is_single_char_literal(const string& value) {
  string s = trim(value);
  if (s.size() < 3 || s.front() != '\'' || s.back() != '\'') return false;
  bool escaped = false;
  for (size_t i = 1; i < s.size() - 1; ++i) {
    if (escaped) escaped = false;
    else if (s[i] == '\\') escaped = true;
    else if (s[i] == '\'') return false;
  }
  return !escaped;
}

bool parse_member_call(const string& text, string& receiver, string& handler,
                       vector<string>& args, bool* outputs_written) {
  if (outputs_written) *outputs_written = false;
  string value = trim(text);
  // A member call inside an argument is not the outer call's receiver.
  // In particular f(message route.Run()) must check route as a message
  // target, not as the ordinary value "f(message route".
  size_t dot = string::npos;
  int nesting = 0;
  bool quoted = false, escaped = false;
  for (size_t index = 0; index < value.size(); ++index) {
    char c = value[index];
    if (quoted) {
      if (escaped) escaped = false;
      else if (c == '\\') escaped = true;
      else if (c == '"') quoted = false;
      continue;
    }
    if (c == '"') { quoted = true; continue; }
    if (c == '(' || c == '[') ++nesting;
    else if (c == ')' || c == ']') --nesting;
    else if (c == '.' && nesting == 0) dot = index;
  }
  auto lp = value.find('(', dot == string::npos ? 0 : dot);
  auto rp = value.rfind(')');
  if (dot == string::npos || lp == string::npos || rp != value.size() - 1 || dot >= lp)
    return false;
  receiver = trim(value.substr(0, dot));
  handler = trim(value.substr(dot + 1, lp - dot - 1));
  if (outputs_written) *outputs_written = true;
  if (receiver.empty() || handler.empty()) return false;
  string inside = value.substr(lp + 1, rp - lp - 1);
  args.clear();
  if (!trim(inside).empty()) args = split_top_level(inside, ',');
  return true;
}

// Phase 20: `Executor` and `FileIO` are compiler-recognized pinned-capability
// forms, not general nominal types registered with the rest of the type
// system. Both the checker and native codegen decompose their builder-chain
// and qualified-construction syntax through these shared textual helpers
// rather than threading a new value type through every generic expression
// path. This keeps the restriction that neither value can be stored, copied,
// or passed through an ordinary expression position "for free": nothing
// outside these targeted call sites recognizes the resulting pseudo-type
// strings ("executor" / "FileIO") as meaningful.
bool parse_executor_chain(const string& text,
                                 vector<std::pair<string, vector<string>>>& calls) {
  string value = trim(text);
  calls.clear();
  while (true) {
    string callee;
    vector<string> args;
    if (parse_simple_call(value, callee, args) && callee == "Executor" && args.empty()) {
      std::reverse(calls.begin(), calls.end());
      return true;
    }
    string receiver, method;
    vector<string> call_args;
    if (!parse_member_call(value, receiver, method, call_args)) return false;
    calls.emplace_back(std::move(method), std::move(call_args));
    value = std::move(receiver);
  }
}

const std::set<string>& executor_config_methods() {
  static const std::set<string> methods = {
      "threads", "max_threads", "queue_capacity", "affinity", "priority"};
  return methods;
}

bool parse_fileio_open(const string& text, vector<string>& args) {
  string receiver, method;
  if (!parse_member_call(text, receiver, method, args)) return false;
  return receiver == "FileIO" && method == "open" && args.size() == 2;
}




bool executor_typed(const std::unordered_map<string, string>& env,
                    const string& name) {
  auto it = env.find(trim(name));
  return it != env.end() && canonical_type_name(it->second) == "executor";
}

bool fileio_typed(const std::unordered_map<string, string>& env,
                  const string& name) {
  auto it = env.find(trim(name));
  return it != env.end() && canonical_type_name(it->second) == "FileIO";
}

// Phase 20 -- the name-level capability predicate. Boundary checks use the
// Checker's phase20_capability_type (fileio_semantics.inc), which adds Agent
// A's structural scoped-type fact (object fields, nested collections). Agent
// D must not reimplement FileIO lifecycle, Range borrow scoping, collection
// escape, or domain effects itself.

// Ordinary synchronous helper functions may borrow FileIO/Range as a plain
// parameter (docs/MOSS_PHASE_20_FILE_IO_AND_EXECUTORS.md sec. 9.3: "Ordinary
// synchronous helper calls may borrow a FileIO temporarily"); they may not
// be returned, stored, or cross a message/reply/executor.invoke/domain
// boundary (phase20_is_nontransferable_capability, above, still applies to
// those positions). `Executor` has no such allowance: it has no legal use
// outside `main` at all.


bool parse_fileio_chunks_source(const string& source, string& fileio_receiver,
                                string& size_expression) {
  string method;
  vector<string> arguments;
  if (!parse_member_call(source, fileio_receiver, method, arguments)) return false;
  if (method != "chunks" || arguments.size() != 1) return false;
  size_expression = arguments.front();
  return true;
}

bool parse_enum_case_expression(const string& expression, string& enum_name,
                                       string& case_name, vector<string>& fields,
                                       bool& called) {
  string value = trim(expression);
  called = parse_member_call(value, enum_name, case_name, fields);
  if (called) return plain_identifier(enum_name) && plain_identifier(case_name);
  auto dot = value.find('.');
  if (dot == string::npos || value.find('.', dot + 1) != string::npos) return false;
  enum_name = trim(value.substr(0, dot));
  case_name = trim(value.substr(dot + 1));
  fields.clear();
  return plain_identifier(enum_name) && plain_identifier(case_name);
}

// A bare `receiver.method` is a callable only inside a functional stage.  It
// remains statically bound to one concrete receiver type and never becomes a
// general runtime method value.
bool parse_bound_method_callable(const string& text, string& receiver,
                                        string& method) {
  string value = trim(text);
  if (value.find('(') != string::npos || value.find(')') != string::npos)
    return false;
  auto dot = value.rfind('.');
  if (dot == string::npos) return false;
  receiver = trim(value.substr(0, dot));
  method = trim(value.substr(dot + 1));
  return plain_identifier(receiver) && plain_identifier(method) && receiver != "_";
}

size_t matching_paren(const string& text, size_t open) {
  if (open >= text.size() || text[open] != '(') return string::npos;
  int depth = 0;
  bool in_str = false, esc = false;
  for (size_t i = open; i < text.size(); ++i) {
    char c = text[i];
    if (in_str) {
      if (esc) esc = false;
      else if (c == '\\') esc = true;
      else if (c == '"') in_str = false;
      continue;
    }
    if (c == '"') { in_str = true; continue; }
    if (c == '(') ++depth;
    else if (c == ')' && --depth == 0) return i;
  }
  return string::npos;
}

// Parentheses are grouping only when they enclose the complete expression.
// Normalize that common case before expression-kind recognition so, for
// example, `(values |> count)` has the same type as `values |> count`.
string strip_redundant_outer_parentheses(string value) {
  value = trim(std::move(value));
  while (value.size() >= 2 && value.front() == '(' && value.back() == ')' &&
         matching_paren(value, 0) == value.size() - 1)
    value = trim(value.substr(1, value.size() - 2));
  return value;
}

std::optional<vector<string>> parse_vector_literal(const string& expression) {
  string value = strip_redundant_outer_parentheses(expression);
  if (value.size() < 2 || value.front() != '[' || value.back() != ']')
    return std::nullopt;
  int depth = 0;
  bool in_str = false, esc = false;
  for (size_t i = 0; i < value.size(); ++i) {
    char c = value[i];
    if (in_str) {
      if (esc) esc = false;
      else if (c == '\\') esc = true;
      else if (c == '"') in_str = false;
      continue;
    }
    if (c == '"') { in_str = true; continue; }
    if (c == '[') ++depth;
    else if (c == ']' && --depth == 0 && i != value.size() - 1)
      return std::nullopt;  // For example, [x][0] is an indexed expression.
  }
  if (in_str || depth != 0) return std::nullopt;
  string inside = trim(value.substr(1, value.size() - 2));
  return inside.empty() ? vector<string>{} : split_top_level(inside, ',');
}

size_t top_level_assignment(const string& text) {
  int par = 0, br = 0, sq = 0;
  bool in_str = false, esc = false;
  for (size_t i = 0; i < text.size(); ++i) {
    char c = text[i];
    if (in_str) {
      if (esc) esc = false;
      else if (c == '\\') esc = true;
      else if (c == '"') in_str = false;
      continue;
    }
    if (c == '"') { in_str = true; continue; }
    if (c == '(') ++par;
    else if (c == ')') --par;
    else if (c == '{') ++br;
    else if (c == '}') --br;
    else if (c == '[') ++sq;
    else if (c == ']') --sq;
    else if (c == '=' && par == 0 && br == 0 && sq == 0) {
      char before = i ? text[i - 1] : '\0';
      char after = i + 1 < text.size() ? text[i + 1] : '\0';
      if (before != '=' && before != '!' && before != '<' && before != '>' &&
          after != '=') return i;
    }
  }
  return string::npos;
}

size_t top_level_colon(const string& text) {
  int par = 0, br = 0, sq = 0;
  bool in_str = false, esc = false;
  for (size_t i = 0; i < text.size(); ++i) {
    char c = text[i];
    if (in_str) {
      if (esc) esc = false;
      else if (c == '\\') esc = true;
      else if (c == '"') in_str = false;
      continue;
    }
    if (c == '"') { in_str = true; continue; }
    if (c == '(') ++par;
    else if (c == ')') --par;
    else if (c == '{') ++br;
    else if (c == '}') --br;
    else if (c == '[') ++sq;
    else if (c == ']') --sq;
    else if (c == ':' && par == 0 && br == 0 && sq == 0) return i;
  }
  return string::npos;
}

size_t top_level_field_dot(const string& text) {
  int par = 0, br = 0, sq = 0;
  bool in_str = false, esc = false;
  size_t dot = string::npos;
  for (size_t i = 0; i < text.size(); ++i) {
    char c = text[i];
    if (in_str) {
      if (esc) esc = false;
      else if (c == '\\') esc = true;
      else if (c == '"') in_str = false;
      continue;
    }
    if (c == '"') { in_str = true; continue; }
    if (c == '(') ++par;
    else if (c == ')') --par;
    else if (c == '{') ++br;
    else if (c == '}') --br;
    else if (c == '[') ++sq;
    else if (c == ']') --sq;
    else if (c == '.' && par == 0 && br == 0 && sq == 0) dot = i;
  }
  return dot;
}

// Named object constructor arguments use '=' in the preferred surface syntax.
// The ':' spelling remains a compatibility form while the frontend migrates.
bool parse_named_argument(const string& text, string& name, string& value) {
  size_t equal = top_level_assignment(text);
  size_t colon = top_level_colon(text);
  size_t delimiter = string::npos;
  if (equal != string::npos && (colon == string::npos || equal < colon)) delimiter = equal;
  else if (colon != string::npos) delimiter = colon;
  if (delimiter == string::npos) return false;
  name = trim(text.substr(0, delimiter));
  value = trim(text.substr(delimiter + 1));
  return plain_identifier(name) && !value.empty();
}

static vector<string> split_pipeline_stages(string expression) {
  expression = trim(std::move(expression));
  vector<string> stages;
  int par = 0, br = 0, sq = 0;
  bool in_str = false, esc = false;
  size_t start = 0;
  for (size_t i = 0; i + 1 < expression.size(); ++i) {
    char c = expression[i];
    if (in_str) {
      if (esc) esc = false;
      else if (c == '\\') esc = true;
      else if (c == '"') in_str = false;
      continue;
    }
    if (c == '"') { in_str = true; continue; }
    if (c == '(') ++par;
    else if (c == ')') --par;
    else if (c == '{') ++br;
    else if (c == '}') --br;
    else if (c == '[') ++sq;
    else if (c == ']') --sq;
    if (c == '|' && expression[i + 1] == '>' && par == 0 && br == 0 && sq == 0) {
      stages.push_back(trim(expression.substr(start, i - start)));
      start = i + 2;
      ++i;
    }
  }
  if (stages.empty()) return {};
  stages.push_back(trim(expression.substr(start)));
  return stages;
}

const vector<FunctionalOperationDescriptor>& functional_operations() {
  static const vector<FunctionalOperationDescriptor> operations = {
      {"map", FunctionalNodeKind::Map, "map(transform)"},
      {"filter", FunctionalNodeKind::Filter, "filter(predicate)"},
      {"reduce", FunctionalNodeKind::Reduce, "reduce(initial, combine)"},
      {"sum", FunctionalNodeKind::Sum, "sum"},
      {"count", FunctionalNodeKind::Count, "count"},
      {"any", FunctionalNodeKind::Any, "any(predicate)"},
      {"all", FunctionalNodeKind::All, "all(predicate)"},
  };
  return operations;
}

static std::optional<FunctionalNodeKind> functional_stage_kind(const string& name) {
  auto operation = std::find_if(
      functional_operations().begin(), functional_operations().end(),
      [&](const FunctionalOperationDescriptor& candidate) {
        return candidate.name == name;
      });
  if (operation != functional_operations().end()) return operation->kind;
  return std::nullopt;
}

// This recognizes the functional source surface but deliberately does not
// decide whether the source is a collection.  The typed checker makes that
// decision so legacy/general scalar pipelines keep their existing meaning.
std::optional<ParsedFunctionalPipeline> parse_functional_pipeline(
    const string& expression) {
  auto parts = split_pipeline_stages(expression);
  if (parts.size() < 2) return std::nullopt;
  ParsedFunctionalPipeline pipeline;
  pipeline.source = parts.front();
  for (size_t index = 1; index < parts.size(); ++index) {
    string callee;
    vector<string> arguments;
    bool call = parse_simple_call(parts[index], callee, arguments);
    if (!call) callee = trim(parts[index]);
    auto kind = functional_stage_kind(callee);
    if (!kind) return std::nullopt;
    ParsedFunctionalStage stage;
    stage.kind = *kind;
    stage.raw = parts[index];
    if (call) stage.arguments = std::move(arguments);
    pipeline.stages.push_back(std::move(stage));
  }
  return pipeline;
}

bool functional_terminal_kind(FunctionalNodeKind kind) {
  return kind == FunctionalNodeKind::Reduce || kind == FunctionalNodeKind::Sum ||
      kind == FunctionalNodeKind::Count || kind == FunctionalNodeKind::Any ||
      kind == FunctionalNodeKind::All;
}

string normalize_pipeline(string expression) {
  expression = trim(std::move(expression));
  auto stages = split_pipeline_stages(expression);
  if (stages.empty()) return expression;
  string value = stages.front();
  for (size_t i = 1; i < stages.size(); ++i) {
    string stage = stages[i];
    string callee;
    vector<string> args;
    if (parse_simple_call(stage, callee, args)) {
      std::ostringstream call;
      call << callee << "(" << value;
      for (const auto& arg : args) call << ", " << arg;
      call << ")";
      value = call.str();
    } else {
      value = stage + "(" + value + ")";
    }
  }
  return value;
}


string snake_case(const string& s) {
  string out;
  for (size_t i = 0; i < s.size(); ++i) {
    char c = s[i];
    if (std::isupper(static_cast<unsigned char>(c))) {
      if (i && !out.empty() && out.back() != '_') out.push_back('_');
      out.push_back(static_cast<char>(std::tolower(static_cast<unsigned char>(c))));
    } else out.push_back(c);
  }
  return out;
}

template <typename ObjectMap>
static const Method* resolve_object_method(
    const ObjectMap& objects, const string& type, const string& name,
    const vector<string>& argument_types, bool unknown_argument_is_wildcard,
    MethodResolutionFailure* failure) {
  string tname = nominal_template_name(type);
  auto object = objects.find(tname);
  if (object == objects.end()) {
    if (failure) *failure = MethodResolutionFailure::UnknownReceiver;
    return nullptr;
  }
  const Method* found = nullptr;
  bool saw_name = false;
  bool saw_arity = false;
  for (const auto& method : object->second->methods) {
    if (method.name != name) continue;
    saw_name = true;
    if (method.params.size() != argument_types.size()) continue;
    saw_arity = true;
    bool compatible = true;
    for (size_t index = 0; index < argument_types.size(); ++index) {
      if (argument_types[index].empty() && unknown_argument_is_wildcard) continue;
      string param_type = canonical_type_name(method.params[index].type);
      if (param_type == tname && is_nominal_instance_type(type)) {
        param_type = canonical_type_name(type);
      }
      if (argument_types[index].empty() || param_type.empty() ||
          param_type != canonical_type_name(argument_types[index])) {
        compatible = false;
        break;
      }
    }
    if (!compatible) continue;
    if (found) {
      if (failure) *failure = MethodResolutionFailure::Ambiguous;
      return nullptr;
    }
    found = &method;
  }
  if (!found && failure)
    *failure = !saw_name ? MethodResolutionFailure::MissingMethod
                         : !saw_arity ? MethodResolutionFailure::WrongArity
                                      : MethodResolutionFailure::IncompatibleArguments;
  return found;
}





const Method* resolve_object_method(
    const std::unordered_map<string, ObjectType*>& objects,
    const string& type, const string& name, const vector<string>& argument_types,
    bool unknown_argument_is_wildcard, MethodResolutionFailure* failure) {
  return resolve_object_method<std::unordered_map<string, ObjectType*>>(
      objects, type, name, argument_types, unknown_argument_is_wildcard, failure);
}

const Method* resolve_object_method(
    const std::unordered_map<string, const ObjectType*>& objects,
    const string& type, const string& name, const vector<string>& argument_types,
    bool unknown_argument_is_wildcard, MethodResolutionFailure* failure) {
  return resolve_object_method<std::unordered_map<string, const ObjectType*>>(
      objects, type, name, argument_types, unknown_argument_is_wildcard, failure);
}

