bool valid_checked_string_literal_spelling(const string& source) {
  if (!is_single_string_literal(source)) return false;
  for (size_t index = 1; index + 1 < source.size(); ++index) {
    if (source[index] != '\\') continue;
    std::uint32_t ignored = 0;
    const size_t next = parse_rust_escape(source, index, ignored);
    if (next == string::npos || next > source.size() - 1) return false;
    index = next - 1;
  }
  return true;
}

// H3 producer input comes only from the occurrence lowerer's retained,
// canonical checked-body-v1 bytes and hash.
std::optional<CheckedPrivateChainBody> common_checked_body(
    const Program& program, const Function& function) {
  if (!function.open_summary || !function.open_summary->scheme_complete ||
      !function.open_summary->occurrence_ledger_complete ||
      !function.checked_body_ir_v1_occurrence_lowered ||
      !function.checked_body_ir_v1_bytes ||
      !function.checked_body_ir_v1_hash || !program.type_context)
  {
    return std::nullopt;
  }
  const auto& summary = *function.open_summary;
  try {
    CheckedPrivateChainBody body;
    body.statements = checked_ir::decode_checked_body_v1(
        *function.checked_body_ir_v1_bytes, *program.type_context,
        summary.parameter_types, summary.result_type,
        *function.checked_body_ir_v1_hash);
    if (checked_ir::encode_checked_body_v1(body.statements) !=
            *function.checked_body_ir_v1_bytes ||
        checked_ir::compute_checked_body_hash_v1(body.statements) !=
            *function.checked_body_ir_v1_hash)
      return std::nullopt;
    body.semantic_hash = *function.checked_body_ir_v1_hash;
    body.dependencies = extract_semantic_dependencies(body.statements);
    return body;
  } catch (const std::invalid_argument&) {
    return std::nullopt;
  }
}

moss::TypeRef imported_abi_v10_type(
    const abi_v10::WireType& wire, const moss::TypeContext& context,
    std::uint32_t variable_count, unsigned depth) {
  if (depth >= 64) return nullptr;
  switch (wire.kind) {
    case abi_v10::WireTypeKind::Primitive:
      return moss::Type::primitive(wire.identity);
    case abi_v10::WireTypeKind::Builtin: {
      vector<moss::TypeRef> arguments;
      for (const auto& argument : wire.arguments) {
        auto term = imported_abi_v10_type(argument, context, variable_count,
                                          depth + 1);
        if (!term) return nullptr;
        arguments.push_back(term);
      }
      return moss::Type::builtin(wire.identity, std::move(arguments));
    }
    case abi_v10::WireTypeKind::Nominal: {
      auto declaration = context.find_id(wire.identity);
      if (!declaration || declaration->kind != moss::DeclarationKind::Record ||
          declaration->inferred_slot_count() != wire.arguments.size())
        return nullptr;
      vector<std::pair<string, moss::TypeRef>> substitutions;
      std::size_t index = 0;
      for (const auto& field : declaration->fields) {
        if (!field.inferred) continue;
        auto term = imported_abi_v10_type(wire.arguments[index++], context,
                                          variable_count, depth + 1);
        if (!term) return nullptr;
        substitutions.emplace_back(field.name, term);
      }
      return moss::Type::nominal_bound(
          declaration, declaration->program_name, std::move(substitutions));
    }
    case abi_v10::WireTypeKind::BoundVar:
      return wire.ordinal < variable_count
          ? moss::Type::var(moss::TypeVarId{0, 0, wire.ordinal}) : nullptr;
    case abi_v10::WireTypeKind::Unit:
      return moss::Type::unit();
    case abi_v10::WireTypeKind::Enum: {
      auto declaration = context.find_id(wire.identity);
      if (!declaration || declaration->kind != moss::DeclarationKind::Enum)
        return nullptr;
      return moss::Type::enumeration_bound(declaration,
                                            declaration->program_name);
    }
    case abi_v10::WireTypeKind::Domain:
      return nullptr;
  }
  return nullptr;
}

static abi_v10::Access imported_abi_v10_access(Effect effect) {
  return effect == Effect::Consume ? abi_v10::Access::Consume :
      effect == Effect::Write ? abi_v10::Access::Write :
                                abi_v10::Access::Read;
}

static Effect imported_abi_v10_effect(abi_v10::Access access) {
  return access == abi_v10::Access::Consume ? Effect::Consume :
      access == abi_v10::Access::Write ? Effect::Write : Effect::Read;
}

moss::AccessMode imported_abi_v10_requirement_access(
    abi_v10::Access access) {
  switch (access) {
    case abi_v10::Access::Read: return moss::AccessMode::Read;
    case abi_v10::Access::Write: return moss::AccessMode::Write;
    case abi_v10::Access::Consume: return moss::AccessMode::Consume;
  }
  throw abi_v10::Error("SOURCE_FREE_SUMMARY_INVALID",
                       "ABI-v10 requirement access mode is unsupported");
}

