static bool abi_v10_checked_vector_literal_summary_candidate(
    const abi_v10::Summary& summary) {
  if (summary.requirements.size() != 1 ||
      !abi_v10::checked_body_hash_valid(summary.body_semantic_hash) ||
      summary.provenance_id.empty() || !summary.dependencies.empty() ||
      summary.observable_effect_bits != 0 ||
      !summary.observable_effect_tags.empty())
    return false;
  std::function<bool(const abi_v10::WireType&, const abi_v10::WireType&)>
      same_wire_type = [&](const abi_v10::WireType& left,
                           const abi_v10::WireType& right) {
    if (left.kind != right.kind || left.identity != right.identity ||
        left.ordinal != right.ordinal ||
        left.arguments.size() != right.arguments.size()) return false;
    for (std::size_t index = 0; index < left.arguments.size(); ++index)
      if (!same_wire_type(left.arguments[index], right.arguments[index]))
        return false;
    return true;
  };
  const auto& requirement = summary.requirements.front();
  std::function<bool(const abi_v10::WireType&)> valid_variables =
      [&](const abi_v10::WireType& type) {
    if (type.kind == abi_v10::WireTypeKind::BoundVar &&
        type.ordinal >= summary.variable_count) return false;
    return std::all_of(type.arguments.begin(), type.arguments.end(),
                       valid_variables);
  };
  if (requirement.operation != "builtin:vector-literal" ||
      requirement.parent != 0 || !requirement.dependencies.empty() ||
      requirement.access != abi_v10::Access::Read ||
      requirement.arguments.empty() ||
      requirement.arguments.size() > 64 ||
      requirement.argument_access != vector<abi_v10::Access>(
          requirement.arguments.size(), abi_v10::Access::Read) ||
      !valid_variables(requirement.receiver) ||
      !std::all_of(requirement.arguments.begin(), requirement.arguments.end(),
                   valid_variables) ||
      !requirement.result ||
      requirement.result->kind != abi_v10::WireTypeKind::Builtin ||
      requirement.result->identity != "vector" ||
      requirement.result->arguments.size() != 1 ||
      !same_wire_type(summary.result, *requirement.result) ||
      !same_wire_type(requirement.result->arguments.front(),
                      requirement.receiver))
    return false;
  if (!std::any_of(requirement.arguments.begin(),
      requirement.arguments.end(), [&](const abi_v10::WireType& argument) {
    return same_wire_type(argument, requirement.receiver);
  }))
    return false;
  std::map<std::uint32_t, abi_v10::WireType> substitutions;
  std::function<bool(std::uint32_t, const abi_v10::WireType&,
                     std::set<std::uint32_t>&)> occurs =
      [&](std::uint32_t ordinal, const abi_v10::WireType& type,
          std::set<std::uint32_t>& visiting) {
    if (type.kind == abi_v10::WireTypeKind::BoundVar) {
      if (type.ordinal == ordinal) return true;
      const auto bound = substitutions.find(type.ordinal);
      if (bound != substitutions.end()) {
        if (!visiting.insert(type.ordinal).second) return true;
        const bool found = occurs(ordinal, bound->second, visiting);
        visiting.erase(type.ordinal);
        if (found) return true;
      }
    }
    for (const auto& argument : type.arguments)
      if (occurs(ordinal, argument, visiting)) return true;
    return false;
  };
  std::function<bool(abi_v10::WireType, abi_v10::WireType)> unify =
      [&](abi_v10::WireType left, abi_v10::WireType right) {
    auto dereference = [&](abi_v10::WireType& type) {
      std::set<std::uint32_t> visited;
      while (type.kind == abi_v10::WireTypeKind::BoundVar) {
        const auto found = substitutions.find(type.ordinal);
        if (found == substitutions.end()) break;
        if (!visited.insert(type.ordinal).second) return false;
        type = found->second;
      }
      return true;
    };
    if (!dereference(left) || !dereference(right)) return false;
    if (left.kind == abi_v10::WireTypeKind::BoundVar &&
        right.kind == abi_v10::WireTypeKind::BoundVar &&
        left.ordinal == right.ordinal) return true;
    if (left.kind == abi_v10::WireTypeKind::BoundVar) {
      std::set<std::uint32_t> visiting;
      if (occurs(left.ordinal, right, visiting)) return false;
      substitutions.emplace(left.ordinal, std::move(right));
      return true;
    }
    if (right.kind == abi_v10::WireTypeKind::BoundVar) {
      std::set<std::uint32_t> visiting;
      if (occurs(right.ordinal, left, visiting)) return false;
      substitutions.emplace(right.ordinal, std::move(left));
      return true;
    }
    if (left.kind != right.kind || left.identity != right.identity ||
        left.ordinal != right.ordinal ||
        left.arguments.size() != right.arguments.size())
      return false;
    for (std::size_t index = 0; index < left.arguments.size(); ++index)
      if (!unify(left.arguments[index], right.arguments[index])) return false;
    return true;
  };
  for (const auto& argument : requirement.arguments)
    if (!unify(requirement.receiver, argument)) return false;
  return true;
}

static bool abi_v10_collection_loop_summary_candidate(
    const abi_v10::Summary& summary) {
  const auto bound_zero = [](const abi_v10::WireType& type) {
    return type.kind == abi_v10::WireTypeKind::BoundVar &&
        type.ordinal == 0 && type.arguments.empty();
  };
  const auto primitive = [](const abi_v10::WireType& type,
                            std::string_view name) {
    return type.kind == abi_v10::WireTypeKind::Primitive &&
        type.identity == name && type.arguments.empty();
  };
  if (summary.variable_count != 1 || summary.parameters.size() != 2 ||
      summary.parameter_access != vector<abi_v10::Access>{
          abi_v10::Access::Read, abi_v10::Access::Read} ||
      summary.parameters[0].kind != abi_v10::WireTypeKind::Builtin ||
      summary.parameters[0].identity != "vector" ||
      summary.parameters[0].arguments.size() != 1 ||
      !bound_zero(summary.parameters[0].arguments.front()) ||
      !bound_zero(summary.parameters[1]) ||
      (!primitive(summary.result, "int") && !primitive(summary.result, "bool")) ||
      !summary.dependencies.empty() || summary.observable_effect_bits != 0 ||
      summary.observable_effect_tags != vector<string>{"may_panic"} ||
      !abi_v10::checked_body_hash_valid(summary.body_semantic_hash) ||
      summary.provenance_id.empty() || summary.requirements.size() != 2)
    return false;
  const auto& index = summary.requirements[0];
  const auto& equality = summary.requirements[1];
  return index.operation == "builtin:index" && index.parent == 0 &&
      index.access == abi_v10::Access::Read &&
      index.receiver.kind == abi_v10::WireTypeKind::Builtin &&
      index.receiver.identity == "vector" &&
      index.receiver.arguments.size() == 1 &&
      bound_zero(index.receiver.arguments.front()) &&
      index.arguments.size() == 1 && index.argument_access.size() == 1 &&
      index.argument_access.front() == abi_v10::Access::Read &&
      primitive(index.arguments.front(), "int") && index.result &&
      bound_zero(*index.result) &&
      equality.operation == "operator:==" && equality.parent == 0 &&
      equality.access == abi_v10::Access::Read &&
      bound_zero(equality.receiver) && equality.arguments.size() == 1 &&
      equality.argument_access.size() == 1 &&
      equality.argument_access.front() == abi_v10::Access::Read &&
      bound_zero(equality.arguments.front()) && equality.result &&
      primitive(*equality.result, "bool") &&
      !index.provenance_id.empty() && !equality.provenance_id.empty();
}

// The checker can also produce the same Count/Index/equality relations for a
// straight-line Count binding followed by an early return. Keep that body on
// the shared occurrence path and validate each operation and both return
// paths against the exact open summary.
static bool abi_v10_collection_count_branch_summary_candidate(
    const abi_v10::Summary& summary) {
  return abi_v10_collection_loop_summary_candidate(summary) &&
      summary.result.kind == abi_v10::WireTypeKind::Primitive &&
      summary.result.identity == "int";
}

